import { readFileSync } from "node:fs";

// Every Jira project key in use (RRDSCRUM, RRDPLAT, RRDDOCS, ...), so the commit shows in the ticket's Development panel.
const JIRA_KEY_PATTERN = /^[A-Z][A-Z0-9]+-\d+: \S/;

/**
 * @param {string} message
 * @returns {string | undefined} the problem, or undefined when the message is fine
 */
function checkCommitMessage(message) {
  const subject = message.split("\n")[0] ?? "";
  // Merge, revert and fixup commits are generated by git and rewritten before they reach main.
  if (/^(Merge |Revert "|fixup! |squash! )/.test(subject)) return undefined;
  if (JIRA_KEY_PATTERN.test(subject)) return undefined;
  return `commit-msg: the subject must start with a Jira key, like "RRDPLAT-104: what changed". Got: "${subject}"`;
}

/** @param {string} messageFile path git passes to the commit-msg hook */
export function commitMsg(messageFile) {
  const problem = checkCommitMessage(readFileSync(messageFile, "utf8"));
  if (problem) console.error(problem);
  return problem ? 1 : 0;
}
